func testLLMActiveModelPairToOneSetOpLLMProviderProfileRevisionUsingLLMProfileRevision(t *testing.T) {
	var err error

	ctx := context.Background()
	tx := MustTx(boil.BeginTx(ctx, nil))
	defer func() { _ = tx.Rollback() }()

	var a LLMActiveModelPair
	var b, c LLMProviderProfileRevision

	seed := randomize.NewSeed()
	if err = randomize.Struct(seed, &a, llmActiveModelPairDBTypes, false, strmangle.SetComplement(llmActiveModelPairPrimaryKeyColumns, llmActiveModelPairColumnsWithoutDefault)...); err != nil {
		t.Fatal(err)
	}
	if err = randomize.Struct(seed, &b, llmProviderProfileRevisionDBTypes, false, strmangle.SetComplement(llmProviderProfileRevisionPrimaryKeyColumns, llmProviderProfileRevisionColumnsWithoutDefault)...); err != nil {
		t.Fatal(err)
	}
	if err = randomize.Struct(seed, &c, llmProviderProfileRevisionDBTypes, false, strmangle.SetComplement(llmProviderProfileRevisionPrimaryKeyColumns, llmProviderProfileRevisionColumnsWithoutDefault)...); err != nil {
		t.Fatal(err)
	}

	if err := a.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}
	if err = b.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}

	for i, x := range []*LLMProviderProfileRevision{&b, &c} {
		err = a.SetLLMProfileRevision(ctx, tx, i != 0, x)
		if err != nil {
			t.Fatal(err)
		}

		if a.R.LLMProfileRevision != x {
			t.Error("relationship struct not set to correct value")
		}

		if x.R.LLMProfileRevisionLLMActiveModelPairs[0] != &a {
			t.Error("failed to append to foreign relationship struct")
		}
		if !queries.Equal(a.LLMProfileRevisionID, x.ID) {
			t.Error("foreign key was wrong value", a.LLMProfileRevisionID)
		}

		zero := reflect.Zero(reflect.TypeOf(a.LLMProfileRevisionID))
		reflect.Indirect(reflect.ValueOf(&a.LLMProfileRevisionID)).Set(zero)

		if err = a.Reload(ctx, tx); err != nil {
			t.Fatal("failed to reload", err)
		}

		if !queries.Equal(a.LLMProfileRevisionID, x.ID) {
			t.Error("foreign key was wrong value", a.LLMProfileRevisionID, x.ID)
		}
	}
}

